INSERT INTO feature VALUES('rule-respect','rules','Case analysis respects rules','presented-types','implemented','notable',NULL,'A case over a presented type must give equal answers on both sides of every rule, the kernel re-deriving the check; a case at a structural fixpoint''s root, past any parameters after the one it recurses on, is read as the fixpoint, its own calls unfolded as deep as the rule''s sides hold constructors. A case that is no fixpoint rests on the laws that `respects` names, as a fold does: the encoder of a layout over the members of its model. A fold over each index of a family takes the index as an argument before the term. The check stands the fold at the index that the root of each rule states, and a fold at one index owes nothing to a rule at another index. A fold into a returner with pure effects gives each term one value, so the check reads its call at a variable of a rule as that value: such a fold respects a rule that drops a variable, and a rule that swaps two variables. A fold with a parameter after the term keeps its call.','core-checker kernel-core','corpus/model/identity/set-fold.gandr corpus/pathological/data/nested-call-tells-apart.gandr corpus/model/identity/state-passing.gandr corpus/pathological/identity/state-passing.gandr corpus/model/layouts/signal-in-one-wire.gandr corpus/pathological/layouts/signal-in-one-wire.gandr corpus/model/desc/fold-over-family.gandr corpus/pathological/desc/fold-over-family.gandr corpus/model/desc/fold-drops-variable.gandr corpus/pathological/desc/fold-drops-variable.gandr corpus/model/desc/fold-swaps-variables.gandr corpus/pathological/desc/fold-swaps-variables.gandr','corpus/model/identity/state-passing.gandr','#357');
